$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);\TNL\Admin\Users::init($db);$db->exec("CREATE TABLE admins(id INTEGER PRIMARY KEY,username TEXT);INSERT INTO admins VALUES(1,'Admin')");foreach(['alice','bob','carl'] as $name)\TNL\Admin\Users::create($db,['username'=>$name,'display_name'=>$name,'domain'=>'company.test','password'=>'test-password-only']);
