contactCheck(Book::read($db,$bob,$id)['email']==='ideal@xempresa.com','public contact readable by colleague');$hidden=Book::read($db,$bob,$locked);contactCheck($hidden['first_name']==='Secreto'&&$hidden['company']==='X Empresa'&&$hidden['email']===null&&$hidden['phone']===null,'locked contacts keep public metadata and mask email and phone on server');
