Book::request($db,$bob,$locked);Book::request($db,$bob,$locked);contactCheck(Book::notifications($db,$alice)===1&&count(Book::permissions($db,$alice,$locked))===1,'read request notifies owner and repeated click is idempotent');contactDenied(fn()=>Book::decide($db,$carl,$locked,$bob['principal'],'granted'),'non-owner cannot grant access');Book::decide($db,$alice,$locked,$bob['principal'],'granted');contactCheck(Book::read($db,$bob,$locked)['email']==='secret@protected.test'&&Book::notifications($db,$bob)===1,'owner grants reading and recipient gets notification');Book::seen($db,$bob);contactCheck(Book::notifications($db,$bob)===0,'opening contact decisions clears notification');Book::decide($db,$alice,$locked,$bob['principal'],'revoked');contactCheck(Book::read($db,$bob,$locked)['email']===null,'revocation immediately masks protected fields');contactCheck(Book::read($db,$admin,$locked)['email']===null,'admin export role does not bypass private contact permissions');
contactDenied(fn()=>Book::exportCsv($db,$bob),'only admins may export contacts');$csv=Book::exportCsv($db,$admin);contactCheck(str_contains($csv,'ideal@xempresa.com')&&!str_contains($csv,'secret@protected.test'),'admin export excludes locked private contacts');Book::decide($db,$alice,$locked,$admin['principal'],'granted');contactCheck(str_contains(Book::exportCsv($db,$admin),'secret@protected.test'),'admin may export private contact after explicit permission');
