$dir=sys_get_temp_dir().'/tnl-contact-search-'.bin2hex(random_bytes(5));mkdir($dir,0700);$store=new \TNL\Mail\ExternalAccount($db,$dir);$store->save('employee:2',['email'=>'bob@company.test','imap_host'=>'imap.company.test','smtp_host'=>'smtp.company.test'],'synthetic');$store->save('employee:3',['email'=>'carl@company.test','imap_host'=>'imap.company.test','smtp_host'=>'smtp.company.test'],'synthetic');$store->recordSent('employee:2','ideal@xempresa.com','Cotización cliente','El pedido está listo','<quote@company.test>');$store->recordSent('employee:3','ideal@xempresa.com','Correo de Carl','No debe aparecer','<private@company.test>');$local=GlobalSearch::local($db,$bob,'juangaldamez');contactCheck(count($local['sent'])===1&&$local['sent'][0]['title']==='Cotización cliente','global name search expands authorized contact email and finds own mail');$terms=GlobalSearch::terms($db,$bob,'Secreto');contactCheck(!in_array('secret@protected.test',$terms,true),'global search cannot expand locked contact email');Book::decide($db,$alice,$locked,$bob['principal'],'granted');contactCheck(in_array('secret@protected.test',GlobalSearch::terms($db,$bob,'Secreto'),true),'global search expands contact email after permission');\TNL\Mail\InternalMail::send($db,1,'bob','Reunión equipo','El presupuesto está aprobado');\TNL\Mail\InternalMail::send($db,1,'carl','Reunión privada','El presupuesto no es público');$local=GlobalSearch::local($db,$bob,'presupuesto');contactCheck(count($local['internal'])===1&&$local['internal'][0]['title']==='Reunión equipo','body search respects internal mail participants');$local=GlobalSearch::local($db,$admin,'presupuesto');contactCheck($local['internal']===[],'admin role does not expose employee internal chats');contactDenied(fn()=>GlobalSearch::remote($db,$bob,'pedido',$dir,'employee:3'),'cannot search another user external mailbox');
